1	import * as vscode from 'vscode';
2	import { BoardItem, CheckRun, CIState, GHLabel, GHUser, LinkedPR, PRFile, RateLimit, RunwayData, ReviewInfo, StandupData, StandupRepoGroup, StandupSection } from './types';
3	
4	const GH_GRAPHQL = 'https://api.github.com/graphql';
5	
6	// The ordered column list
7	const COLUMN_ORDER = [
8	  'Needs Grooming',
9	  'Grooming in Progress',
10	  'Grooming to Review',
11	  'TODO',
12	  'In Progress',
13	  'Ready For Review',
14	  'Ready For QA',
15	  'QA Done',
16	  'Done',
17	  'Blocked',
18	];
19	
20	async function getToken(): Promise<string> {
21	  const session = await vscode.authentication.getSession(
22	    'github',
23	    ['repo', 'read:org', 'read:user', 'project'],
24	    { createIfNone: true }
25	  );
26	  return session.accessToken;
27	}
28	
29	async function graphql<T>(token: string, query: string, variables: Record<string, unknown>): Promise<T> {
30	  const resp = await fetch(GH_GRAPHQL, {
31	    method: 'POST',
32	    headers: {
33	      Authorization: `bearer ${token}`,
34	      'Content-Type': 'application/json',
35	    },
36	    body: JSON.stringify({ query, variables }),
37	  });
38	
39	  if (!resp.ok) {
40	    throw new Error(`GitHub API HTTP ${resp.status}: ${resp.statusText}`);
41	  }
42	
43	  const json = (await resp.json()) as { data?: T; errors?: { message: string }[] };
44	
45	  if (json.errors?.length) {
46	    throw new Error(`GitHub GraphQL: ${json.errors.map((e) => e.message).join(', ')}`);
47	  }
48	
49	  if (!json.data) {
50	    throw new Error('GitHub GraphQL: no data returned');
51	  }
52	
53	  return json.data;
54	}
55	
56	// Query to fetch open PRs from a repo, with their closing issue references
57	// Used to find PRs that fix board issues but aren't directly tracked on the board
58	const REPO_OPEN_PRS_QUERY = `
59	query GetRepoOpenPRs($owner: String!, $repo: String!, $cursor: String) {
60	  repository(owner: $owner, name: $repo) {
61	    pullRequests(states: OPEN, first: 50, after: $cursor) {
62	      pageInfo { hasNextPage endCursor }
63	      nodes {
64	        number title url state isDraft createdAt updatedAt
65	        additions deletions headRefName
66	        author { login avatarUrl }
67	        assignees(first: 10) { nodes { login avatarUrl } }
68	        repository { name owner { login } }
69	        commits(last: 1) { nodes { commit { statusCheckRollup { state } } } }
70	        reviews(last: 5) { nodes { state author { login avatarUrl } } }
71	        reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login avatarUrl } } } }
72	        closingIssuesReferences(first: 20) { nodes { number } }
73	      }
74	    }
75	  }
76	}
77	`;
78	
79	// The big GraphQL query - works for both org and user
80	// Note: body is NOT fetched here (too large) — loaded on demand via fetchItemBody
81	const PROJECT_ITEMS_QUERY = `
82	query GetProjectItems($login: String!, $number: Int!, $isOrg: Boolean!, $cursor: String) {
83	  rateLimit { remaining limit resetAt }
84	  viewer { login }
85	  org: organization(login: $login) @include(if: $isOrg) {
86	    projectV2(number: $number) {
87	      title
88	      items(first: 100, after: $cursor) {
89	        pageInfo { hasNextPage endCursor }
90	        nodes {
91	          id
92	          type
93	          fieldValues(first: 20) {
94	            nodes {
95	              ... on ProjectV2ItemFieldSingleSelectValue {
96	                name
97	                field { ... on ProjectV2SingleSelectField { name } }
98	              }
99	              ... on ProjectV2ItemFieldIterationValue {
100	                title
101	                field { ... on ProjectV2IterationField { name } }
102	              }
103	            }
104	          }
105	          content {
106	            ... on Issue {
107	              __typename
108	              number title url state createdAt updatedAt
109	              author { login avatarUrl }
110	              assignees(first: 10) { nodes { login avatarUrl } }
111	              labels(first: 10) { nodes { name color } }
112	              milestone { title number dueOn }
113	              repository { name owner { login } }
114	            }
115	            ... on PullRequest {
116	              __typename
117	              number title url state isDraft createdAt updatedAt
118	              additions deletions headRefName
119	              author { login avatarUrl }
120	              assignees(first: 10) { nodes { login avatarUrl } }
121	              labels(first: 10) { nodes { name color } }
122	              milestone { title number dueOn }
123	              repository { name owner { login } }
124	              commits(last: 1) {
125	                nodes { commit { statusCheckRollup { state } } }
126	              }
127	              reviews(last: 5) {
128	                nodes { state author { login avatarUrl } }
129	              }
130	              reviewRequests(first: 10) {
131	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
132	              }
133	              closingIssuesReferences(first: 10) {
134	                nodes { number }
135	              }
136	            }
137	          }
138	        }
139	      }
140	    }
141	  }
142	  user: user(login: $login) @skip(if: $isOrg) {
143	    projectV2(number: $number) {
144	      title
145	      items(first: 100, after: $cursor) {
146	        pageInfo { hasNextPage endCursor }
147	        nodes {
148	          id
149	          type
150	          fieldValues(first: 20) {
151	            nodes {
152	              ... on ProjectV2ItemFieldSingleSelectValue {
153	                name
154	                field { ... on ProjectV2SingleSelectField { name } }
155	              }
156	              ... on ProjectV2ItemFieldIterationValue {
157	                title
158	                field { ... on ProjectV2IterationField { name } }
159	              }
160	            }
161	          }
162	          content {
163	            ... on Issue {
164	              __typename
165	              number title url state createdAt updatedAt
166	              author { login avatarUrl }
167	              assignees(first: 10) { nodes { login avatarUrl } }
168	              labels(first: 10) { nodes { name color } }
169	              milestone { title number dueOn }
170	              repository { name owner { login } }
171	            }
172	            ... on PullRequest {
173	              __typename
174	              number title url state isDraft createdAt updatedAt
175	              additions deletions headRefName
176	              author { login avatarUrl }
177	              assignees(first: 10) { nodes { login avatarUrl } }
178	              labels(first: 10) { nodes { name color } }
179	              milestone { title number dueOn }
180	              repository { name owner { login } }
181	              commits(last: 1) {
182	                nodes { commit { statusCheckRollup { state } } }
183	              }
184	              reviews(last: 5) {
185	                nodes { state author { login avatarUrl } }
186	              }
187	              reviewRequests(first: 10) {
188	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
189	              }
190	              closingIssuesReferences(first: 10) {
191	                nodes { number }
192	              }
193	            }
194	          }
195	        }
196	      }
197	    }
198	  }
199	}
200	`;
201	
202	interface RawFieldValueNode {
203	  // Single select
204	  name?: string;
205	  field?: { name?: string };
206	  // Iteration
207	  title?: string;
208	}
209	
210	interface RawProjectNode {
211	  id: string;
212	  type: string;
213	  fieldValues: {
214	    nodes: Array<RawFieldValueNode>;
215	  };
216	  content: RawIssue | RawPR | { __typename: string } | null;
217	}
218	
219	interface RawMilestone {
220	  title: string;
221	  number: number;
222	  dueOn: string | null;
223	}
224	
225	interface RawIssue {
226	  __typename: 'Issue';
227	  number: number;
228	  title: string;
229	  url: string;
230	  state: string;
231	  body: string | null;
232	  createdAt: string;
233	  updatedAt: string;
234	  author: GHUser | null;
235	  assignees: { nodes: GHUser[] } | null;
236	  labels: { nodes: GHLabel[] } | null;
237	  milestone: RawMilestone | null;
238	  repository: { name: string; owner: { login: string } } | null;
239	}
240	
241	interface RawPR {
242	  __typename: 'PullRequest';
243	  number: number;
244	  title: string;
245	  url: string;
246	  state: string;
247	  isDraft: boolean;
248	  body: string | null;
249	  createdAt: string;
250	  updatedAt: string;
251	  additions: number;
252	  deletions: number;
253	  headRefName: string;
254	  author: GHUser | null;
255	  assignees: { nodes: GHUser[] } | null;
256	  labels: { nodes: GHLabel[] } | null;
257	  milestone: RawMilestone | null;
258	  repository: { name: string; owner: { login: string } } | null;
259	  commits: { nodes: Array<{ commit: { statusCheckRollup: { state: string } | null } }> } | null;
260	  reviews: { nodes: Array<{ state: string; author: GHUser }> } | null;
261	  reviewRequests: { nodes: Array<{ requestedReviewer: GHUser | null }> } | null;
262	  closingIssuesReferences: { nodes: Array<{ number: number }> } | null;
263	}
264	
265	interface ProjectData {
266	  title: string;
267	  items: {
268	    pageInfo: { hasNextPage: boolean; endCursor: string | null };
269	    nodes: RawProjectNode[];
270	  };
271	}
272	
273	function extractColumn(node: RawProjectNode, statusFieldName: string): string {
274	  const nodes = node.fieldValues?.nodes ?? [];
275	  for (const fv of nodes) {
276	    if (fv.field?.name === statusFieldName && fv.name) {
277	      return fv.name;
278	    }
279	  }
280	  return 'Uncategorized';
281	}
282	
283	function extractSprint(node: RawProjectNode): { sprint: string; sprintField: string } | undefined {
284	  for (const fv of node.fieldValues?.nodes ?? []) {
285	    if (fv.title !== undefined && fv.field?.name) {
286	      return { sprint: fv.title, sprintField: fv.field.name };
287	    }
288	  }
289	  return undefined;
290	}
