386	/**
387	 * For each repo that has board issues, fetch all open PRs and return those
388	 * that close (via `Fixes #N`, `Closes #N`, etc.) a board issue.
389	 * The linked PR inherits the parent issue's column and sprint.
390	 */
391	async function fetchLinkedPRsFromRepos(
392	  token: string,
393	  issueByRepo: Map<string, Map<number, BoardItem>>,
394	  groups: Record<string, BoardItem[]>
395	): Promise<BoardItem[]> {
396	  const linkedPRMap = new Map<string, BoardItem>(); // `owner/repo#number` → BoardItem
397	  // Track PR numbers already on the board to avoid duplicates
398	  const boardPRKeys = new Set<string>();
399	  for (const items of Object.values(groups)) {
400	    for (const item of items) {
401	      if (item.type === 'PULL_REQUEST') {
402	        boardPRKeys.add(`${item.repositoryOwner}/${item.repository}#${item.number}`);
403	      }
404	    }
405	  }
406	
407	  // Process repos sequentially to avoid saturating GitHub's secondary rate limit,
408	  // which would starve user-triggered requests (e.g. detail panel linked PRs fetch).
409	  for (const [repoKey, issueMap] of issueByRepo.entries()) {
410	    const [repoOwner, repoName] = repoKey.split('/');
411	    let prCursor: string | null = null;
412	
413	    do {
414	      let repoData: { repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } } | null = null;
415	      try {
416	        repoData = await graphql<{ repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } }>(
417	          token,
418	          REPO_OPEN_PRS_QUERY,
419	          { owner: repoOwner, repo: repoName, cursor: prCursor }
420	        );
421	      } catch {
422	        break; // skip repos we can't access
423	      }
424	
425	      const prs = repoData?.repository?.pullRequests?.nodes ?? [];
426	      for (const rawPR of prs) {
427	        const prKey = `${repoOwner}/${repoName}#${rawPR.number}`;
428	        if (boardPRKeys.has(prKey) || linkedPRMap.has(prKey)) continue;
429	
430	        // Check if this PR closes any of our board issues
431	        const closingNums = rawPR.closingIssuesReferences?.nodes?.map((n) => n.number) ?? [];
432	        const parentIssue = closingNums.map((n) => issueMap.get(n)).find((i) => i !== undefined);
433	        if (!parentIssue) continue;
434	
435	        const ciRaw = rawPR.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state ?? 'none';
436	        linkedPRMap.set(prKey, {
437	          id: `linked-${prKey}`,
438	          number: rawPR.number,
439	          title: rawPR.title,
440	          type: 'PULL_REQUEST',
441	          url: rawPR.url,
442	          column: parentIssue.column,
443	          state: rawPR.state,
444	          author: rawPR.author ?? { login: 'unknown', avatarUrl: '' },
445	          assignees: rawPR.assignees?.nodes ?? [],
446	          labels: parentIssue.labels,
447	          repository: repoName,
448	          repositoryOwner: repoOwner,
449	          createdAt: rawPR.createdAt,
450	          updatedAt: rawPR.updatedAt,
451	          isDraft: rawPR.isDraft,
452	          additions: rawPR.additions,
453	          deletions: rawPR.deletions,
454	          headRefName: rawPR.headRefName,
455	          ciState: ciRaw as CIState,
456	          reviews: extractLatestReviews(rawPR.reviews),
457	          reviewRequests: (rawPR.reviewRequests?.nodes ?? [])
458	            .map((r) => r.requestedReviewer)
459	            .filter((r): r is GHUser => r !== null),
460	          closingIssueNumbers: closingNums,
461	          sprint: parentIssue.sprint,
462	          sprintField: parentIssue.sprintField,
463	        });
464	      }
465	
466	      if (repoData?.repository?.pullRequests?.pageInfo?.hasNextPage) {
467	        prCursor = repoData.repository.pullRequests.pageInfo.endCursor;
468	      } else {
469	        prCursor = null;
470	      }
471	    } while (prCursor !== null);
472	  }
473	
474	  return Array.from(linkedPRMap.values());
475	}
