477	/** Assembles a RunwayData snapshot from already-parsed groups and sprints. */
478	function assembleRunwayData(
479	  groups: Record<string, BoardItem[]>,
480	  sprintsSet: Set<string>,
481	  projectTitle: string,
482	  viewerLogin: string,
483	  rateLimit: RateLimit | undefined
484	): RunwayData {
485	  const colOrderLower = COLUMN_ORDER.map((c) => c.toLowerCase());
486	  const knownPresent = Object.keys(groups)
487	    .filter((c) => colOrderLower.includes(c.toLowerCase()))
488	    .sort((a, b) => colOrderLower.indexOf(a.toLowerCase()) - colOrderLower.indexOf(b.toLowerCase()));
489	  const extras = Object.keys(groups).filter((c) => !colOrderLower.includes(c.toLowerCase()));
490	  const columns = [...knownPresent, ...extras];
491	  const totalCount = Object.values(groups).reduce((sum, items) => sum + items.length, 0);
492	  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
493	  const sprints = Array.from(sprintsSet).sort((a, b) => collator.compare(b, a));
494	  return { projectTitle, columns, groups, sprints, lastUpdated: new Date().toISOString(), totalCount, viewerLogin, linkedIssuePRs: [], rateLimit };
495	}
