497	/**
498	 * Fetches all project items with progressive delivery.
499	 * `onPage` is called after each paginated response so the caller can render
500	 * partial data immediately — the board appears after the first ~100 items
501	 * rather than waiting for the full dataset to arrive.
502	 * Groups and sprints are accumulated incrementally so each page only parses
503	 * its own new nodes (O(n) total, not O(n²)).
504	 */
505	export async function fetchProjectData(
506	  owner: string,
507	  projectNumber: number,
508	  isOrg: boolean,
509	  statusFieldName: string,
510	  onPage?: (partial: RunwayData) => void
511	): Promise<RunwayData> {
512	  const token = await getToken();
513	  let projectTitle = '';
514	  let viewerLogin = '';
515	  let cursor: string | null = null;
516	
517	  type ProjectResponse = {
518	    rateLimit?: RateLimit;
519	    viewer: { login: string };
520	    org?: { projectV2: ProjectData };
521	    user?: { projectV2: ProjectData };
522	  };
523	  let lastRateLimit: RateLimit | undefined;
524	
525	  // Incremental state — only new nodes per page are parsed and appended
526	  const groups: Record<string, BoardItem[]> = {};
527	  const sprintsSet = new Set<string>();
528	  const pageDeliveryInterval = 3;
529	  let pageCount = 0;
530	
531	  do {
532	    const data: ProjectResponse = await graphql<ProjectResponse>(
533	      token,
534	      PROJECT_ITEMS_QUERY,
535	      { login: owner, number: projectNumber, isOrg, cursor }
536	    );
537	
538	    if (data.rateLimit) lastRateLimit = data.rateLimit;
539	    if (!viewerLogin) viewerLogin = data.viewer?.login ?? '';
540	
541	    const project: ProjectData | undefined = isOrg ? data.org?.projectV2 : data.user?.projectV2;
542	    if (!project) {
543	      throw new Error(`Project #${projectNumber} not found for ${owner}`);
544	    }
545	
546	    projectTitle = project.title;
547	
548	    for (const node of project.items.nodes) {
549	      const column = extractColumn(node, statusFieldName);
550	      const item = parseItem(node, column);
551	      if (!item) continue;
552	      if (!groups[column]) groups[column] = [];
553	      groups[column].push(item);
554	      if (item.sprint) sprintsSet.add(item.sprint);
555	    }
556	
557	    cursor = project.items.pageInfo.hasNextPage
558	      ? project.items.pageInfo.endCursor
559	      : null;
560	
561	    pageCount++;
562	    // Deliver page 1 immediately for fast first paint; throttle to every nth page
563	    // after that to avoid re-serializing the full growing payload on every page.
564	    if (onPage && (pageCount === 1 || pageCount % pageDeliveryInterval === 0 || cursor === null)) {
565	      onPage(assembleRunwayData(groups, sprintsSet, projectTitle, viewerLogin, lastRateLimit));
566	    }
567	  } while (cursor !== null);
568	
569	  return assembleRunwayData(groups, sprintsSet, projectTitle, viewerLogin, lastRateLimit);
570	}
