659	export async function fetchLinkedPRChecks(
660	  owner: string,
661	  repo: string,
662	  issueNumber: number
663	): Promise<LinkedPR[]> {
664	  const token = await getToken();
665	  const data = await graphql<{
666	    repository: {
667	      issue: {
668	        closingPullRequests: { nodes: RawLinkedPR[] };
669	        timelineItems: { nodes: Array<{ source?: RawLinkedPR }> };
670	      } | null;
671	    } | null;
672	  }>(token, LINKED_PRS_QUERY, { owner, repo, number: issueNumber });
673	
674	  // Merge closing PRs + timeline cross-references, deduplicate by number
675	  const closing = data.repository?.issue?.closingPullRequests?.nodes ?? [];
676	  const crossRefs = (data.repository?.issue?.timelineItems?.nodes ?? [])
677	    .map((n) => n.source)
678	    .filter((s): s is RawLinkedPR => !!s && 'number' in s);
679	
680	  const seen = new Set<number>();
681	  const merged: RawLinkedPR[] = [];
682	  for (const pr of [...closing, ...crossRefs]) {
683	    if (!seen.has(pr.number)) {
684	      seen.add(pr.number);
685	      merged.push(pr);
686	    }
687	  }
688	
689	  if (!merged.length) return [];
690	
691	  // Fetch check runs for each PR in parallel
692	  const results = await Promise.all(
693	    merged.map(async (pr): Promise<LinkedPR> => {
694	      const sha = pr.commits?.nodes?.[0]?.commit?.oid;
695	      const checkRuns = sha ? await fetchCheckRunsForCommit(token, owner, repo, sha) : [];
696	
697	      // Derive overall CI state from check runs
698	      let ciState: CIState = 'none';
699	      if (checkRuns.length) {
700	        if (checkRuns.some((r) => r.status !== 'COMPLETED')) ciState = 'PENDING';
701	        else if (checkRuns.some((r) => r.conclusion === 'FAILURE' || r.conclusion === 'TIMED_OUT')) ciState = 'FAILURE';
702	        else if (checkRuns.every((r) => r.conclusion === 'SUCCESS' || r.conclusion === 'SKIPPED' || r.conclusion === 'NEUTRAL')) ciState = 'SUCCESS';
703	        else ciState = 'PENDING';
704	      }
705	
706	      return {
707	        number: pr.number,
708	        title: pr.title,
709	        url: pr.url,
710	        state: pr.state,
711	        isDraft: pr.isDraft,
712	        headRefName: pr.headRefName,
713	        ciState,
714	        checkRuns,
715	      };
716	    })
717	  );
718	
719	  return results;
720	}
