815	export async function generateStandupData(viewerLogin: string): Promise<{ data: StandupData; markdown: string }> {
816	  const token = await getToken();
817	  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
818	  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
819	
820	  const repoFromUrl = (url: string) => url.replace('https://api.github.com/repos/', '');
821	
822	  async function search(q: string): Promise<RawSearchIssue[]> {
823	    const resp = await fetch(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&per_page=30`, {
824	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
825	    });
826	    if (!resp.ok) return [];
827	    const json = (await resp.json()) as { items: RawSearchIssue[] };
828	    return json.items ?? [];
829	  }
830	
831	  async function fetchCommentedItems(): Promise<RawSearchIssue[]> {
832	    const resp = await fetch(
833	      `https://api.github.com/users/${viewerLogin}/events?per_page=100`,
834	      { headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' } }
835	    );
836	    if (!resp.ok) return [];
837	    const events = (await resp.json()) as RawGitHubEvent[];
838	
839	    const seenUrls = new Set<string>();
840	    const items: RawSearchIssue[] = [];
841	
842	    for (const event of events) {
843	      // Events are newest-first — stop once we're past the 24h window
844	      if (event.created_at < yesterday) break;
845	
846	      const isMyComment =
847	        (event.type === 'IssueCommentEvent' && event.payload.action === 'created') ||
848	        (event.type === 'PullRequestReviewCommentEvent' && event.payload.action === 'created') ||
849	        event.type === 'PullRequestReviewEvent';
850	      if (!isMyComment) continue;
851	
852	      const target = event.payload.issue ?? event.payload.pull_request;
853	      if (!target || seenUrls.has(target.html_url)) continue;
854	      seenUrls.add(target.html_url);
855	
856	      items.push({
857	        number: target.number,
858	        title: target.title,
859	        html_url: target.html_url,
860	        repository_url: `https://api.github.com/repos/${event.repo.name}`,
861	        pull_request: (event.payload.pull_request ?? event.payload.issue?.pull_request) ? { merged_at: null } : undefined,
862	      });
863	    }
864	    return items;
865	  }
