import Foundation

// MARK: - Core GitHub types

struct GHUser: Codable, Hashable {
    let login: String
    let avatarUrl: String
}

struct GHLabel: Codable, Hashable, Identifiable {
    var id: String { name }
    let name: String
    let color: String // hex without #
}

struct GHMilestone: Codable, Hashable {
    let title: String
    let number: Int
    let dueOn: String?
}

enum CIState: String, Codable, Hashable {
    case success = "SUCCESS"
    case failure = "FAILURE"
    case pending = "PENDING"
    case error = "ERROR"
    case expected = "EXPECTED"
    case none = "none"
}

enum ReviewState: String, Codable, Hashable {
    case approved = "APPROVED"
    case changesRequested = "CHANGES_REQUESTED"
    case commented = "COMMENTED"
    case dismissed = "DISMISSED"
    case pending = "PENDING"
}

struct ReviewInfo: Codable, Hashable {
    let state: ReviewState
    let author: GHUser
}

struct CheckRun: Codable, Identifiable, Hashable {
    var id: String { name }
    let name: String
    let status: String
    let conclusion: String?
    let detailsUrl: String?
}

enum ItemType: String, Codable, Hashable {
    case issue = "ISSUE"
    case pullRequest = "PULL_REQUEST"
}

// MARK: - Board item

struct BoardItem: Codable, Identifiable, Hashable {
    let id: String
    let number: Int
    let title: String
    let body: String?
    let type: ItemType
    let url: String
    let column: String
    let state: String
    let author: GHUser
    let assignees: [GHUser]
    let labels: [GHLabel]
    let repository: String
    let repositoryOwner: String
    let createdAt: String
    let updatedAt: String
    let milestone: GHMilestone?
    let sprint: String?
    let sprintField: String?
    // PR-only
    let isDraft: Bool?
    let additions: Int?
    let deletions: Int?
    let headRefName: String?
    let ciState: CIState?
    let reviews: [ReviewInfo]?
    let reviewRequests: [GHUser]?
    let closingIssueNumbers: [Int]?

    var isOpen: Bool { state == "OPEN" }
    var isMerged: Bool { state == "MERGED" }

    var reviewSummary: ReviewSummary {
        guard let reviews = reviews, !reviews.isEmpty else { return .none }
        if reviews.contains(where: { $0.state == .changesRequested }) { return .changesRequested }
        if reviews.contains(where: { $0.state == .approved }) { return .approved }
        return .commented
    }

