    var owner: String = ""
    var projectNumber: Int = 0
    var ownerType: OwnerType = .organization
    var statusFieldName: String = "Status"
    var refreshInterval: Int = 300

    static func load() -> AppConfig {
        let d = UserDefaults.standard
        var c = AppConfig()
        c.owner = d.string(forKey: "owner") ?? ""
        c.projectNumber = d.integer(forKey: "projectNumber")
        c.ownerType = OwnerType(rawValue: d.string(forKey: "ownerType") ?? "") ?? .organization
        c.statusFieldName = d.string(forKey: "statusFieldName").flatMap { $0.isEmpty ? nil : $0 } ?? "Status"
        let ri = d.integer(forKey: "refreshInterval")
        c.refreshInterval = ri == 0 ? 300 : ri
        return c
    }

    func save() {
        let d = UserDefaults.standard
        d.set(owner, forKey: "owner")
        d.set(projectNumber, forKey: "projectNumber")
        d.set(ownerType.rawValue, forKey: "ownerType")
        d.set(statusFieldName, forKey: "statusFieldName")
        d.set(refreshInterval, forKey: "refreshInterval")
    }

    var isConfigured: Bool { !owner.isEmpty && projectNumber > 0 }
}

// MARK: - Owner / project picker types

struct OwnerOption: Identifiable, Hashable {
    var id: String { login }
    let login: String
    let ownerType: OwnerType
}

struct ProjectOption: Identifiable, Hashable {
    var id: Int { number }
    let number: Int
    let title: String
}

