import Foundation
import AuthenticationServices

@MainActor
class OAuthService: NSObject {
    static let clientID     = "Ov23ctNxTjLvxkA3xGVR"
    static let clientSecret = "c1fbe2f89531910e97ba82e5015eaaf9ef577af6"
    static let callbackScheme = "sprinthub"

    private var session: ASWebAuthenticationSession?

    func authenticate() async throws -> String {
        var components = URLComponents(string: "https://github.com/login/oauth/authorize")!
        components.queryItems = [
            URLQueryItem(name: "client_id", value: Self.clientID),
            URLQueryItem(name: "scope", value: "repo read:org read:user project"),
        ]
        let authURL = components.url!

        let callbackURL: URL = try await withCheckedThrowingContinuation { continuation in
            let s = ASWebAuthenticationSession(
                url: authURL,
                callbackURLScheme: Self.callbackScheme
            ) { url, error in
                if let error = error {
                    continuation.resume(throwing: error)
                } else if let url = url {
                    continuation.resume(returning: url)
                } else {
                    continuation.resume(throwing: OAuthError.noCallbackURL)
                }
            }
            s.presentationContextProvider = self
            s.prefersEphemeralWebBrowserSession = false
            self.session = s
            s.start()
        }

        guard let code = URLComponents(url: callbackURL, resolvingAgainstBaseURL: false)?
            .queryItems?.first(where: { $0.name == "code" })?.value
        else { throw OAuthError.noCode }

        return try await exchangeCode(code)
    }

    private func exchangeCode(_ code: String) async throws -> String {
        var req = URLRequest(url: URL(string: "https://github.com/login/oauth/access_token")!)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Accept")
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try JSONEncoder().encode([
            "client_id": Self.clientID,
            "client_secret": Self.clientSecret,
            "code": code,
        ])

        let (data, response) = try await URLSession.shared.data(for: req)
        guard (response as? HTTPURLResponse)?.statusCode == 200 else {
            throw OAuthError.tokenExchangeFailed
        }

        let json = try JSONDecoder().decode([String: String].self, from: data)
        guard let token = json["access_token"], !token.isEmpty else {
            throw OAuthError.noToken(json["error_description"] ?? "Unknown error")
        }
        return token
    }

    enum OAuthError: LocalizedError {
        case noCallbackURL
        case noCode
        case tokenExchangeFailed
        case noToken(String)

        var errorDescription: String? {
            switch self {
            case .noCallbackURL:       return "No callback URL received from GitHub."
            case .noCode:              return "No authorization code in callback URL."
            case .tokenExchangeFailed: return "Failed to exchange authorization code for token."
            case .noToken(let msg):    return "GitHub did not return an access token: \(msg)"
            }
        }
    }
}

extension OAuthService: ASWebAuthenticationPresentationContextProviding {
    nonisolated func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor {
        NSApp.windows.first(where: \.isVisible) ?? NSWindow()
    }
}

