}

// MARK: - Helpers

private let columnOrder = [
    "Needs Grooming", "Grooming in Progress", "Grooming to Review",
    "TODO", "In Progress", "Ready For Review", "Ready For QA",
    "QA Done", "Done", "Blocked",
]

private func extractColumn(_ node: RawProjectNode, statusFieldName: String) -> String {
    for fv in node.fieldValues.nodes.compactMap({ $0 }) {
        if let fieldName = fv.field?.name, fieldName == statusFieldName, let name = fv.name {
            return name
        }
    }
    return "Uncategorized"
}

private func extractSprint(_ node: RawProjectNode) -> (sprint: String, field: String)? {
    for fv in node.fieldValues.nodes.compactMap({ $0 }) {
        if let title = fv.title, let fieldName = fv.field?.name {
            return (title, fieldName)
        }
    }
    return nil
}

private func extractReviews(_ raw: RawNodes<RawReview>?) -> [ReviewInfo] {
    var byReviewer: [String: ReviewInfo] = [:]
    for r in raw?.nodes.compactMap({ $0 }) ?? [] {
        guard let author = r.author else { continue }
        byReviewer[author.login] = ReviewInfo(
            state: ReviewState(rawValue: r.state) ?? .pending,
            author: GHUser(login: author.login, avatarUrl: author.avatarUrl)
        )
    }
    return Array(byReviewer.values)
}

private func parseItem(_ node: RawProjectNode, column: String, statusFieldName: String) -> BoardItem? {
    guard let c = node.content,
          c.__typename == "Issue" || c.__typename == "PullRequest",
          let number = c.number, let title = c.title, let url = c.url,
          let state = c.state, let createdAt = c.createdAt, let updatedAt = c.updatedAt
    else { return nil }

    let sprintInfo = extractSprint(node)
    let author = c.author.map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) }
        ?? GHUser(login: "unknown", avatarUrl: "")
    let assignees = (c.assignees?.nodes.compactMap { $0 } ?? [])
        .map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) }
    let labels = (c.labels?.nodes.compactMap { $0 } ?? [])
        .map { GHLabel(name: $0.name, color: $0.color) }
    let milestone = c.milestone.map {
        GHMilestone(title: $0.title, number: $0.number, dueOn: $0.dueOn)
    }

    let type_: ItemType = c.__typename == "Issue" ? .issue : .pullRequest

    var ciState: CIState = .none
    if type_ == .pullRequest {
        let rawCI = c.commits?.nodes.compactMap({ $0 }).last?.commit.statusCheckRollup?.state ?? "none"
        ciState = CIState(rawValue: rawCI) ?? .none
    }

    return BoardItem(
        id: node.id,
        number: number,
        title: title,
        body: nil,
        type: type_,
        url: url,
        column: column,
        state: state,
        author: author,
        assignees: assignees,
        labels: labels,
        repository: c.repository?.name ?? "",
        repositoryOwner: c.repository?.owner.login ?? "",
        createdAt: createdAt,
        updatedAt: updatedAt,
        milestone: milestone,
        sprint: sprintInfo?.sprint,
        sprintField: sprintInfo?.field,
        isDraft: c.isDraft,
        additions: c.additions,
        deletions: c.deletions,
        headRefName: c.headRefName,
        ciState: type_ == .pullRequest ? ciState : nil,
        reviews: type_ == .pullRequest ? extractReviews(c.reviews) : nil,
        reviewRequests: type_ == .pullRequest
            ? (c.reviewRequests?.nodes.compactMap { $0?.requestedReviewer }.map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) } ?? [])
            : nil,
        closingIssueNumbers: c.closingIssuesReferences?.nodes.compactMap { $0?.number }
    )
}

private func assembleRunwayData(
    groups: [String: [BoardItem]],
    sprints: Set<String>,
    projectTitle: String,
    viewerLogin: String,
    rateLimit: RateLimit?
) -> RunwayData {
    let lowerOrder = columnOrder.map { $0.lowercased() }
    let known = groups.keys.filter { lowerOrder.contains($0.lowercased()) }
        .sorted { lowerOrder.firstIndex(of: $0.lowercased())! < lowerOrder.firstIndex(of: $1.lowercased())! }
    let extras = groups.keys.filter { !lowerOrder.contains($0.lowercased()) }.sorted()
    let columns = known + extras
    let total = groups.values.map(\.count).reduce(0, +)
    let sortedSprints = sprints.sorted { a, b in
        a.localizedStandardCompare(b) == .orderedDescending
    }
    return RunwayData(
        projectTitle: projectTitle,
        columns: columns,
        groups: groups,
        sprints: sortedSprints,
        lastUpdated: ISO8601DateFormatter().string(from: Date()),
        totalCount: total,
        viewerLogin: viewerLogin,
        linkedIssuePRs: [],
        rateLimit: rateLimit
    )
}

// MARK: - Service

struct GitHubService {
    let token: String
    private let graphqlURL = URL(string: "https://api.github.com/graphql")!

    // MARK: GraphQL

    private func graphql<T: Decodable>(_ query: String, variables: [String: Any]) async throws -> T {
        var req = URLRequest(url: graphqlURL)
        req.httpMethod = "POST"
        req.setValue("bearer \(token)", forHTTPHeaderField: "Authorization")
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try JSONSerialization.data(withJSONObject: ["query": query, "variables": variables])

        let (data, resp) = try await URLSession.shared.data(for: req)
        if let http = resp as? HTTPURLResponse, http.statusCode != 200 {
            throw GitHubError.http(http.statusCode)
        }

        if let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let errors = json["errors"] as? [[String: Any]], !errors.isEmpty {
            let msg = errors.compactMap { $0["message"] as? String }.joined(separator: ", ")
            throw GitHubError.graphQL(msg)
        }

        let wrapper = try JSONDecoder().decode(GraphQLResponse<T>.self, from: data)
        guard let result = wrapper.data else { throw GitHubError.noData }
        return result
    }

    // MARK: REST

    private func rest<T: Decodable>(_ path: String) async throws -> T {
        var req = URLRequest(url: URL(string: "https://api.github.com\(path)")!)
        req.setValue("bearer \(token)", forHTTPHeaderField: "Authorization")
        req.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
        let (data, _) = try await URLSession.shared.data(for: req)
        return try JSONDecoder().decode(T.self, from: data)
    }

    // MARK: - Fetch project data

    private static let projectItemsQuery = """
    query GetProjectItems($login: String!, $number: Int!, $isOrg: Boolean!, $cursor: String) {
      rateLimit { remaining limit resetAt }
      viewer { login }
      org: organization(login: $login) @include(if: $isOrg) {
        projectV2(number: $number) {
          title
          items(first: 100, after: $cursor) {
            pageInfo { hasNextPage endCursor }
            nodes {
              id type
              fieldValues(first: 20) {
                nodes {
                  ... on ProjectV2ItemFieldSingleSelectValue {
                    name field { ... on ProjectV2SingleSelectField { name } }
                  }
                  ... on ProjectV2ItemFieldIterationValue {
                    title field { ... on ProjectV2IterationField { name } }
                  }
                }
              }
              content {
                ... on Issue {
                  __typename number title url state createdAt updatedAt
                  author { login avatarUrl }
                  assignees(first: 10) { nodes { login avatarUrl } }
                  labels(first: 10) { nodes { name color } }
                  milestone { title number dueOn }
                  repository { name owner { login } }
                }
                ... on PullRequest {
                  __typename number title url state isDraft createdAt updatedAt
                  additions deletions headRefName
                  author { login avatarUrl }
                  assignees(first: 10) { nodes { login avatarUrl } }
                  labels(first: 10) { nodes { name color } }
                  milestone { title number dueOn }
                  repository { name owner { login } }
                  commits(last: 1) { nodes { commit { statusCheckRollup { state } } } }
                  reviews(last: 5) { nodes { state author { login avatarUrl } } }
                  reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login avatarUrl } } } }
                  closingIssuesReferences(first: 10) { nodes { number } }
                }
              }
            }
          }
        }
      }
      user: user(login: $login) @skip(if: $isOrg) {
        projectV2(number: $number) {
          title
          items(first: 100, after: $cursor) {
            pageInfo { hasNextPage endCursor }
            nodes {
              id type
              fieldValues(first: 20) {
                nodes {
                  ... on ProjectV2ItemFieldSingleSelectValue {
                    name field { ... on ProjectV2SingleSelectField { name } }
                  }
                  ... on ProjectV2ItemFieldIterationValue {
                    title field { ... on ProjectV2IterationField { name } }
                  }
                }
              }
              content {
                ... on Issue {
                  __typename number title url state createdAt updatedAt
                  author { login avatarUrl }
                  assignees(first: 10) { nodes { login avatarUrl } }
                  labels(first: 10) { nodes { name color } }
                  milestone { title number dueOn }
                  repository { name owner { login } }
                }
                ... on PullRequest {
                  __typename number title url state isDraft createdAt updatedAt
                  additions deletions headRefName
                  author { login avatarUrl }
                  assignees(first: 10) { nodes { login avatarUrl } }
                  labels(first: 10) { nodes { name color } }
                  milestone { title number dueOn }
                  repository { name owner { login } }
                  commits(last: 1) { nodes { commit { statusCheckRollup { state } } } }
                  reviews(last: 5) { nodes { state author { login avatarUrl } } }
                  reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login avatarUrl } } } }
                  closingIssuesReferences(first: 10) { nodes { number } }
                }
              }
            }
          }
        }
      }
    }
    """

    func fetchProjectData(
        owner: String,
        projectNumber: Int,
        isOrg: Bool,
        statusFieldName: String,
        onPage: ((RunwayData) -> Void)? = nil
    ) async throws -> RunwayData {
        var groups: [String: [BoardItem]] = [:]
        var sprintsSet = Set<String>()
        var cursor: String? = nil
        var projectTitle = ""
        var viewerLogin = ""
        var lastRateLimit: RateLimit?
        var pageCount = 0

        repeat {
            var vars: [String: Any] = [
                "login": owner, "number": projectNumber, "isOrg": isOrg,
            ]
            if let c = cursor { vars["cursor"] = c }

            let data: ProjectItemsResponse = try await graphql(Self.projectItemsQuery, variables: vars)

            if let rl = data.rateLimit {
                lastRateLimit = RateLimit(remaining: rl.remaining, limit: rl.limit, resetAt: rl.resetAt)
            }
            if viewerLogin.isEmpty { viewerLogin = data.viewer.login }

            guard let project = isOrg ? data.org?.projectV2 : data.user?.projectV2 else {
                throw GitHubError.projectNotFound(owner, projectNumber)
            }
            projectTitle = project.title

            for node in project.items.nodes.compactMap({ $0 }) {
                let column = extractColumn(node, statusFieldName: statusFieldName)
                guard let item = parseItem(node, column: column, statusFieldName: statusFieldName) else { continue }
                groups[column, default: []].append(item)
                if let sprint = item.sprint { sprintsSet.insert(sprint) }
            }

            cursor = project.items.pageInfo.hasNextPage ? project.items.pageInfo.endCursor : nil
            pageCount += 1

            if let onPage, (pageCount == 1 || pageCount % 3 == 0 || cursor == nil) {
                onPage(assembleRunwayData(groups: groups, sprints: sprintsSet,
                                         projectTitle: projectTitle, viewerLogin: viewerLogin,
                                         rateLimit: lastRateLimit))
            }
        } while cursor != nil

        return assembleRunwayData(groups: groups, sprints: sprintsSet,
                                  projectTitle: projectTitle, viewerLogin: viewerLogin,
                                  rateLimit: lastRateLimit)
    }

    // MARK: - Fetch linked PRs from repos

    private static let repoPRsQuery = """
    query GetRepoOpenPRs($owner: String!, $repo: String!, $cursor: String) {
      repository(owner: $owner, name: $repo) {
        pullRequests(states: OPEN, first: 50, after: $cursor) {
          pageInfo { hasNextPage endCursor }
          nodes {
            number title url state isDraft createdAt updatedAt additions deletions headRefName
            author { login avatarUrl }
            assignees(first: 10) { nodes { login avatarUrl } }
            repository { name owner { login } }
            commits(last: 1) { nodes { commit { statusCheckRollup { state } } } }
            reviews(last: 5) { nodes { state author { login avatarUrl } } }
            reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login avatarUrl } } } }
            closingIssuesReferences(first: 20) { nodes { number } }
          }
        }
      }
    }
    """

    func fetchLinkedPRs(for groups: [String: [BoardItem]]) async throws -> [BoardItem] {
        // Build index: repoKey → (issueNumber → BoardItem)
        var issueByRepo: [String: [Int: BoardItem]] = [:]
        var boardPRKeys = Set<String>()

        for items in groups.values {
            for item in items {
                if item.type == .pullRequest {
                    boardPRKeys.insert("\(item.repositoryOwner)/\(item.repository)#\(item.number)")
                }
                if item.type == .issue, !item.repositoryOwner.isEmpty, !item.repository.isEmpty {
                    let key = "\(item.repositoryOwner)/\(item.repository)"
                    issueByRepo[key, default: [:]][item.number] = item
                }
            }
        }

        guard !issueByRepo.isEmpty else { return [] }

        var linked: [String: BoardItem] = [:]

        for (repoKey, issueMap) in issueByRepo {
            let parts = repoKey.split(separator: "/", maxSplits: 1)
            guard parts.count == 2 else { continue }
            let (repoOwner, repoName) = (String(parts[0]), String(parts[1]))
            var prCursor: String? = nil

            repeat {
                var vars: [String: Any] = ["owner": repoOwner, "repo": repoName]
                if let c = prCursor { vars["cursor"] = c }

                guard let data: RepoPRsResponse = try? await graphql(Self.repoPRsQuery, variables: vars) else { break }

                for rawPR in data.repository?.pullRequests.nodes.compactMap({ $0 }) ?? [] {
                    let prKey = "\(repoOwner)/\(repoName)#\(rawPR.number)"
                    guard !boardPRKeys.contains(prKey), linked[prKey] == nil else { continue }

                    let closingNums = rawPR.closingIssuesReferences?.nodes.compactMap { $0?.number } ?? []
                    guard let parent = closingNums.compactMap({ issueMap[$0] }).first else { continue }

                    let ciRaw = rawPR.commits?.nodes.compactMap({ $0 }).last?.commit.statusCheckRollup?.state ?? "none"
                    linked[prKey] = BoardItem(
                        id: "linked-\(prKey)",
                        number: rawPR.number,
                        title: rawPR.title,
                        body: nil,
                        type: .pullRequest,
                        url: rawPR.url,
                        column: parent.column,
                        state: rawPR.state,
                        author: rawPR.author.map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) }
                            ?? GHUser(login: "unknown", avatarUrl: ""),
                        assignees: rawPR.assignees?.nodes.compactMap { $0 }.map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) } ?? [],
                        labels: parent.labels,
                        repository: repoName,
                        repositoryOwner: repoOwner,
                        createdAt: rawPR.createdAt,
                        updatedAt: rawPR.updatedAt,
                        milestone: nil,
                        sprint: parent.sprint,
                        sprintField: parent.sprintField,
                        isDraft: rawPR.isDraft,
                        additions: rawPR.additions,
                        deletions: rawPR.deletions,
                        headRefName: rawPR.headRefName,
                        ciState: CIState(rawValue: ciRaw) ?? .none,
                        reviews: extractReviews(rawPR.reviews),
                        reviewRequests: rawPR.reviewRequests?.nodes.compactMap { $0?.requestedReviewer }
                            .map { GHUser(login: $0.login, avatarUrl: $0.avatarUrl) },
                        closingIssueNumbers: closingNums
                    )
                }

                prCursor = data.repository?.pullRequests.pageInfo.hasNextPage == true
                    ? data.repository?.pullRequests.pageInfo.endCursor
                    : nil
            } while prCursor != nil
        }

        return Array(linked.values)
    }

    // MARK: - Settings pickers

    func fetchOwners() async throws -> [OwnerOption] {
        let query = """
        query {
          viewer {
            login
            organizations(first: 100) { nodes { login } }
          }
        }
        """
        let data: SettingsOwnersResponse = try await graphql(query, variables: [:])
        var result = [OwnerOption(login: data.viewer.login, ownerType: .user)]
        result += data.viewer.organizations.nodes.compactMap { $0 }
            .map { OwnerOption(login: $0.login, ownerType: .organization) }
        return result
    }

    func fetchProjects(owner: String, ownerType: OwnerType) async throws -> [ProjectOption] {
        let query = """
        query($login: String!, $isOrg: Boolean!) {
          org: organization(login: $login) @include(if: $isOrg) {
            projectsV2(first: 50, orderBy: { field: UPDATED_AT, direction: DESC }) { nodes { number title } }
          }
          user: user(login: $login) @skip(if: $isOrg) {
            projectsV2(first: 50, orderBy: { field: UPDATED_AT, direction: DESC }) { nodes { number title } }
          }
        }
        """
        let isOrg = ownerType == .organization
        let data: SettingsProjectsResponse = try await graphql(query, variables: ["login": owner, "isOrg": isOrg])
        let nodes = isOrg
            ? data.org?.projectsV2.nodes.compactMap { $0 }
            : data.user?.projectsV2.nodes.compactMap { $0 }
        return (nodes ?? []).map { ProjectOption(number: $0.number, title: $0.title) }
    }

    // MARK: - Viewer login

    func fetchViewerLogin() async throws -> String {
        struct Resp: Decodable { let viewer: V; struct V: Decodable { let login: String } }
        let data: Resp = try await graphql("query { viewer { login } }", variables: [:])
        return data.viewer.login
    }
}

// MARK: - Errors

enum GitHubError: LocalizedError {
    case http(Int)
    case graphQL(String)
    case noData
    case projectNotFound(String, Int)

    var errorDescription: String? {
        switch self {
        case .http(let code):              return "GitHub API returned HTTP \(code)."
        case .graphQL(let msg):            return "GitHub GraphQL error: \(msg)"
        case .noData:                      return "GitHub returned no data."
        case .projectNotFound(let o, let n): return "Project #\(n) not found for \(o)."
        }
    }
}

