import SwiftUI

@MainActor
class AppState: ObservableObject {
    // Auth
    @Published var isAuthenticated = false
    @Published var token: String? = nil

    // Data
    @Published var runwayData: RunwayData? = nil
    @Published var isLoading = false
    @Published var isRefreshing = false
    @Published var error: String? = nil

    // Config
    @Published var config: AppConfig = .load()

    // UI state
    @Published var selectedSprint: String? = nil
    @Published var selectedColumn: String? = nil

    private let keychain = KeychainService()
    private let oauth = OAuthService()
    private var refreshTask: Task<Void, Never>? = nil

    init() {
        if let t = keychain.loadToken() {
            token = t
            isAuthenticated = true
        }
    }

    // MARK: - Auth

    func signIn() async {
        do {
            let t = try await oauth.authenticate()
            keychain.saveToken(t)
            token = t
            isAuthenticated = true
            error = nil
            if config.isConfigured { await load() }
        } catch {
            self.error = error.localizedDescription
        }
    }

    func signOut() {
        keychain.deleteToken()
        token = nil
        isAuthenticated = false
        runwayData = nil
        error = nil
        cancelAutoRefresh()
    }

    // MARK: - Data

    func load() async {
        guard let token, config.isConfigured else { return }
        isLoading = true
        error = nil
        await fetchData(token: token)
        isLoading = false
        scheduleAutoRefresh()
    }

    func refresh() async {
        guard let token, config.isConfigured, !isRefreshing else { return }
        isRefreshing = true
        error = nil
        await fetchData(token: token)
        isRefreshing = false
    }

    private func fetchData(token: String) async {
        let svc = GitHubService(token: token)
        do {
            let data = try await svc.fetchProjectData(
                owner: config.owner,
                projectNumber: config.projectNumber,
                isOrg: config.ownerType == .organization,
                statusFieldName: config.statusFieldName
            ) { [weak self] partial in
                Task { @MainActor [weak self] in
                    self?.runwayData = partial
                }
            }
            // Append linked PRs in the background after first paint
            var finalData = data
            if let linkedPRs = try? await svc.fetchLinkedPRs(for: data.groups) {
                finalData = RunwayData(
                    projectTitle: data.projectTitle,
                    columns: data.columns,
                    groups: data.groups,
                    sprints: data.sprints,
                    lastUpdated: data.lastUpdated,
                    totalCount: data.totalCount,
                    viewerLogin: data.viewerLogin,
                    linkedIssuePRs: linkedPRs,
                    rateLimit: data.rateLimit
                )
            }
            runwayData = finalData
            if selectedSprint == nil, let first = finalData.sprints.first {
                selectedSprint = first
            }
        } catch {
            self.error = error.localizedDescription
        }
    }

    // MARK: - Auto-refresh

    func scheduleAutoRefresh() {
        cancelAutoRefresh()
        let interval = TimeInterval(config.refreshInterval)
        refreshTask = Task { [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(interval))
                guard !Task.isCancelled else { break }
                await self?.refresh()
            }
        }
    }

    func cancelAutoRefresh() {
        refreshTask?.cancel()
        refreshTask = nil
    }

    // MARK: - Computed helpers

    var currentSprintItems: [BoardItem] {
        guard let data = runwayData else { return [] }
        return data.groups.values.flatMap { $0 }
            .filter { selectedSprint == nil || $0.sprint == selectedSprint }
    }

    var openPRsNeedingReview: [BoardItem] {
        runwayData?.allPRs.filter { $0.isOpen && $0.isDraft != true } ?? []
    }

    var boardItemCount: Int { runwayData?.totalCount ?? 0 }
    var openPRCount: Int { openPRsNeedingReview.count }
}

