import SwiftUI

struct PopoverView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        VStack(spacing: 0) {
            // Header
            HStack {
                Image(systemName: "bolt.circle.fill")
                    .foregroundStyle(.blue)
                Text("SprintHub")
                    .font(.headline)
                Spacer()
                Button {
                    Task { await appState.refresh() }
                } label: {
                    Image(systemName: appState.isRefreshing ? "arrow.triangle.2.circlepath" : "arrow.clockwise")
                        .rotationEffect(appState.isRefreshing ? .degrees(360) : .zero)
                        .animation(appState.isRefreshing ? .linear(duration: 1).repeatForever(autoreverses: false) : .default, value: appState.isRefreshing)
                }
                .buttonStyle(.plain)
                .disabled(!appState.isAuthenticated || appState.isRefreshing)

                Button {
                    openDashboard()
                } label: {
                    Image(systemName: "arrow.up.forward.app")
                }
                .buttonStyle(.plain)
                .help("Open Dashboard")
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 12)

            Divider()

            if !appState.isAuthenticated {
                unauthenticatedContent
            } else if appState.isLoading {
                loadingContent
            } else if let data = appState.runwayData {
                scrollContent(data: data)
            } else if !appState.config.isConfigured {
                notConfiguredContent
            } else {
                emptyContent
            }
        }
        .frame(width: 360)
        .background(.regularMaterial)
        .task {
            if appState.isAuthenticated && appState.runwayData == nil && appState.config.isConfigured {
                await appState.load()
            }
        }
    }

    // MARK: - Content states

    private var unauthenticatedContent: some View {
        VStack(spacing: 12) {
            Image(systemName: "person.badge.key")
                .font(.system(size: 32))
                .foregroundStyle(.secondary)
            Text("Sign in to get started")
                .font(.subheadline)
                .foregroundStyle(.secondary)
            Button("Sign in with GitHub") {
                Task { await appState.signIn() }
            }
            .buttonStyle(.borderedProminent)
        }
        .frame(maxWidth: .infinity)
        .padding(32)
    }

    private var loadingContent: some View {
        VStack(spacing: 12) {
            ProgressView()
            Text("Loading sprint data…")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity)
        .padding(32)
    }

    private var notConfiguredContent: some View {
        VStack(spacing: 12) {
            Image(systemName: "gearshape")
                .font(.system(size: 32))
                .foregroundStyle(.secondary)
            Text("Set up your project in Settings")
                .font(.subheadline)
                .foregroundStyle(.secondary)
            Button("Open Dashboard") { openDashboard() }
                .buttonStyle(.borderedProminent)
        }
        .frame(maxWidth: .infinity)
        .padding(32)
    }

    private var emptyContent: some View {
        VStack(spacing: 8) {
            Image(systemName: "checkmark.circle")
                .font(.system(size: 32))
                .foregroundStyle(.green)
            Text("All clear")
                .font(.subheadline.bold())
            Text("No items found for this sprint.")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity)
        .padding(32)
    }

    // MARK: - Main scroll content

    private func scrollContent(data: RunwayData) -> some View {
        ScrollView {
            VStack(spacing: 0) {
                // Sprint + project summary
                summaryRow(data: data)
                Divider()

                // Open PRs needing attention
                if !appState.openPRsNeedingReview.isEmpty {
                    sectionHeader("Pull Requests", count: appState.openPRsNeedingReview.count, systemImage: "arrow.triangle.pull")
                    ForEach(appState.openPRsNeedingReview.prefix(5)) { pr in
                        PopoverPRRow(item: pr)
                        Divider().padding(.leading, 44)
                    }
                }

                // Board items in active sprint
                let sprintItems = appState.currentSprintItems.filter { $0.type == .issue && $0.isOpen }
                if !sprintItems.isEmpty {
                    sectionHeader("Board Items", count: sprintItems.count, systemImage: "square.stack")
                    ForEach(sprintItems.prefix(8)) { item in
                        PopoverItemRow(item: item)
                        Divider().padding(.leading, 44)
                    }
                }

                // Footer: last updated + open dashboard
                VStack(spacing: 8) {
                    if let rl = data.rateLimit {
                        Text("API rate limit: \(rl.remaining)/\(rl.limit)")
                            .font(.caption2)
                            .foregroundStyle(.tertiary)
                    }
                    Button("Open Full Dashboard") { openDashboard() }
                        .buttonStyle(.plain)
                        .font(.caption)
                        .foregroundStyle(.blue)
                }
                .frame(maxWidth: .infinity)
                .padding(12)
            }
        }
        .frame(maxHeight: 520)
    }

    // MARK: - Helpers

    private func summaryRow(data: RunwayData) -> some View {
        HStack(spacing: 16) {
            VStack(alignment: .leading, spacing: 2) {
                Text(data.projectTitle)
                    .font(.subheadline.bold())
                    .lineLimit(1)
                if let sprint = appState.selectedSprint {
                    Text(sprint)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }
            Spacer()
            HStack(spacing: 12) {
                statBadge(value: data.totalCount, label: "Items", color: .blue)
                statBadge(value: appState.openPRCount, label: "PRs", color: .orange)
            }
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 10)
    }

    private func statBadge(value: Int, label: String, color: Color) -> some View {
        VStack(spacing: 1) {
            Text("\(value)")
                .font(.system(size: 18, weight: .bold, design: .rounded))
                .foregroundStyle(color)
            Text(label)
                .font(.caption2)
                .foregroundStyle(.secondary)
        }
    }

    private func sectionHeader(_ title: String, count: Int, systemImage: String) -> some View {
        HStack(spacing: 6) {
            Image(systemName: systemImage)
                .font(.caption.bold())
                .foregroundStyle(.secondary)
            Text(title.uppercased())
                .font(.caption.bold())
                .foregroundStyle(.secondary)
            Spacer()
            Text("\(count)")
                .font(.caption2.bold())
                .foregroundStyle(.tertiary)
        }
        .padding(.horizontal, 16)
        .padding(.top, 12)
        .padding(.bottom, 4)
    }

    private func openDashboard() {
        NSApp.activate(ignoringOtherApps: true)
        // Open the window scene
        if let window = NSApp.windows.first(where: { $0.title == "SprintHub" }) {
            window.makeKeyAndOrderFront(nil)
        } else {
            NSApp.sendAction(Selector(("showWindow:")), to: nil, from: nil)
        }
    }
}

// MARK: - Row components

private struct PopoverPRRow: View {
    let item: BoardItem

    var body: some View {
        HStack(spacing: 10) {
            CIStateDot(state: item.ciState ?? .none)
                .frame(width: 8, height: 8)
                .padding(.leading, 16)

            VStack(alignment: .leading, spacing: 2) {
                Text(item.title)
                    .font(.caption.bold())
                    .lineLimit(1)
                Text("\(item.repositoryOwner)/\(item.repository) #\(item.number)")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            if item.isDraft == true {
                draftBadge
            }

            ReviewDots(reviews: item.reviews ?? [])
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 6)
        .contentShape(Rectangle())
        .onTapGesture { openURL(item.url) }
    }

    private var draftBadge: some View {
        Text("Draft")
            .font(.caption2.bold())
            .padding(.horizontal, 5)
            .padding(.vertical, 2)
            .background(.gray.opacity(0.2), in: Capsule())
            .foregroundStyle(.secondary)
    }
}

private struct PopoverItemRow: View {
    let item: BoardItem

    var body: some View {
        HStack(spacing: 10) {
            Circle()
                .fill(item.isOpen ? Color.green : .gray)
                .frame(width: 8, height: 8)
                .padding(.leading, 16)

            VStack(alignment: .leading, spacing: 2) {
                Text(item.title)
                    .font(.caption.bold())
                    .lineLimit(1)
                Text(item.column)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Text("#\(item.number)")
                .font(.caption2)
                .foregroundStyle(.tertiary)
                .padding(.trailing, 16)
        }
        .padding(.vertical, 6)
        .contentShape(Rectangle())
        .onTapGesture { openURL(item.url) }
    }
}

// MARK: - Shared small components

struct CIStateDot: View {
    let state: CIState

    var body: some View {
        Circle().fill(color)
    }

    private var color: Color {
        switch state {
        case .success:  return .green
        case .failure, .error: return .red
        case .pending, .expected: return .orange
        case .none:     return .gray.opacity(0.4)
        }
    }
}

struct ReviewDots: View {
    let reviews: [ReviewInfo]

    var body: some View {
        HStack(spacing: 3) {
            ForEach(Array(reviews.prefix(3).enumerated()), id: \.offset) { _, r in
                Circle()
                    .fill(reviewColor(r.state))
                    .frame(width: 7, height: 7)
            }
        }
        .padding(.trailing, 16)
    }

    private func reviewColor(_ state: ReviewState) -> Color {
        switch state {
        case .approved:          return .green
        case .changesRequested:  return .red
        default:                 return .orange
        }
    }
}

private func openURL(_ string: String) {
    guard let url = URL(string: string) else { return }
    NSWorkspace.shared.open(url)
}

