import SwiftUI

enum SidebarItem: String, CaseIterable, Identifiable {
    case board    = "Board"
    case prs      = "Pull Requests"
    case settings = "Settings"

    var id: String { rawValue }

    var systemImage: String {
        switch self {
        case .board:    return "square.stack.3d.up"
        case .prs:      return "arrow.triangle.pull"
        case .settings: return "gearshape"
        }
    }
}

struct ContentView: View {
    @EnvironmentObject var appState: AppState
    @State private var selection: SidebarItem = .board

    var body: some View {
        if !appState.isAuthenticated {
            LoginView()
                .task {
                    // nothing – LoginView drives auth
                }
        } else {
            NavigationSplitView {
                sidebar
            } detail: {
                detailView
                    .navigationTitle(selection.rawValue)
                    .toolbar { toolbarContent }
            }
            .task {
                if appState.runwayData == nil { await appState.load() }
            }
        }
    }

    // MARK: - Sidebar

    private var sidebar: some View {
        List(selection: $selection) {
            Section {
                ForEach(SidebarItem.allCases) { item in
                    Label(item.rawValue, systemImage: item.systemImage)
                        .tag(item)
                        .badge(badgeCount(for: item))
                }
            } header: {
                if let data = appState.runwayData {
                    VStack(alignment: .leading, spacing: 2) {
                        Text(data.projectTitle)
                            .font(.headline)
                            .foregroundStyle(.primary)
                        if let sprint = appState.selectedSprint {
                            Text(sprint)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .padding(.bottom, 4)
                    .textCase(nil)
                }
            }
        }
        .listStyle(.sidebar)
        .navigationSplitViewColumnWidth(min: 200, ideal: 220)
    }

    private func badgeCount(for item: SidebarItem) -> Int? {
        switch item {
        case .prs:
            let c = appState.openPRCount
            return c > 0 ? c : nil
        default:
