import SwiftUI

struct BoardView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        if let data = appState.runwayData {
            boardContent(data: data)
        } else {
            emptyState
        }
    }

    private func boardContent(data: RunwayData) -> some View {
        ScrollView(.horizontal, showsIndicators: true) {
            LazyHStack(alignment: .top, spacing: 12) {
                ForEach(data.columns, id: \.self) { column in
                    let items = filteredItems(data.groups[column] ?? [], sprint: appState.selectedSprint)
                    BoardColumn(title: column, items: items)
                }
            }
            .padding(16)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(NSColor.windowBackgroundColor))
    }

    private func filteredItems(_ items: [BoardItem], sprint: String?) -> [BoardItem] {
        guard let sprint else { return items }
        return items.filter { $0.sprint == sprint }
    }

    private var emptyState: some View {
        VStack(spacing: 12) {
            Image(systemName: "square.stack.3d.up.slash")
                .font(.system(size: 40))
                .foregroundStyle(.tertiary)
            Text("No board data")
                .font(.title3)
                .foregroundStyle(.secondary)
            Text("Configure your project in Settings to get started.")
                .font(.subheadline)
                .foregroundStyle(.tertiary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

