import SwiftUI

struct PRListView: View {
    @EnvironmentObject var appState: AppState
    @State private var searchText = ""
    @State private var selectedPR: BoardItem? = nil

    private var prs: [BoardItem] {
        let all = appState.runwayData?.allPRs ?? []
        let filtered = appState.selectedSprint == nil
            ? all
            : all.filter { $0.sprint == appState.selectedSprint || $0.sprint == nil }
        if searchText.isEmpty { return filtered }
        return filtered.filter {
            $0.title.localizedCaseInsensitiveContains(searchText) ||
            $0.repository.localizedCaseInsensitiveContains(searchText) ||
            "\($0.number)".contains(searchText)
        }
    }

    var body: some View {
        HSplitView {
            // PR list
            VStack(spacing: 0) {
                searchBar
                Divider()
                list
            }
            .frame(minWidth: 320, idealWidth: 380)

            // Detail panel
            if let pr = selectedPR {
                PRDetailPanel(item: pr)
                    .frame(minWidth: 360)
            } else {
                emptyDetail
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    // MARK: - Search bar

    private var searchBar: some View {
        HStack {
            Image(systemName: "magnifyingglass")
                .foregroundStyle(.secondary)
            TextField("Search PRs…", text: $searchText)
                .textFieldStyle(.plain)
            if !searchText.isEmpty {
                Button { searchText = "" } label: {
                    Image(systemName: "xmark.circle.fill")
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
            }
        }
        .padding(10)
        .background(Color(NSColor.controlBackgroundColor))
    }

    // MARK: - List

    private var list: some View {
        List(prs, selection: $selectedPR) { pr in
            PRListRow(item: pr)
                .tag(pr)
        }
        .listStyle(.plain)
        .overlay {
            if prs.isEmpty {
                VStack(spacing: 8) {
                    Image(systemName: "checkmark.circle")
                        .font(.system(size: 32))
                        .foregroundStyle(.green)
                    Text(searchText.isEmpty ? "No pull requests" : "No results")
                        .foregroundStyle(.secondary)
                }
            }
        }
    }

    private var emptyDetail: some View {
        VStack(spacing: 8) {
            Image(systemName: "arrow.triangle.pull")
                .font(.system(size: 36))
                .foregroundStyle(.tertiary)
            Text("Select a pull request")
                .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

// MARK: - PR list row

private struct PRListRow: View {
    let item: BoardItem

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                CIStateDot(state: item.ciState ?? .none)
                    .frame(width: 8, height: 8)

                Text(item.title)
                    .font(.subheadline.bold())
                    .lineLimit(2)

                Spacer()

                if item.isDraft == true {
                    badge("Draft", color: .gray)
                }
            }

            HStack(spacing: 10) {
                Text("\(item.repositoryOwner)/\(item.repository) #\(item.number)")
                    .font(.caption)
                    .foregroundStyle(.secondary)

                Spacer()

                if let additions = item.additions, let deletions = item.deletions {
                    HStack(spacing: 4) {
                        Text("+\(additions)")
                            .foregroundStyle(.green)
                        Text("-\(deletions)")
                            .foregroundStyle(.red)
                    }
                    .font(.caption2.monospaced())
                }

                ReviewDots(reviews: item.reviews ?? [])
                    .padding(.trailing, 0)
            }

            // Labels
            if !item.labels.isEmpty {
                HStack(spacing: 4) {
                    ForEach(item.labels.prefix(4)) { label in
                        LabelBadge(label: label)
                    }
                }
            }
        }
        .padding(.vertical, 4)
    }

    private func badge(_ text: String, color: Color) -> some View {
        Text(text)
            .font(.caption2.bold())
            .padding(.horizontal, 6)
            .padding(.vertical, 2)
            .background(color.opacity(0.15), in: Capsule())
            .foregroundStyle(color)
    }
}

// MARK: - PR detail panel

private struct PRDetailPanel: View {
    let item: BoardItem

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                // Title & meta
                VStack(alignment: .leading, spacing: 8) {
                    HStack(spacing: 8) {
                        CIStateDot(state: item.ciState ?? .none)
                            .frame(width: 10, height: 10)
                        Text(stateLabel)
                            .font(.caption.bold())
                            .foregroundStyle(stateColor)
                    }

                    Text(item.title)
                        .font(.title3.bold())

                    HStack(spacing: 12) {
                        Label("\(item.repositoryOwner)/\(item.repository)", systemImage: "chevron.left.forwardslash.chevron.right")
                        Label("#\(item.number)", systemImage: "number")
                    }
                    .font(.caption)
                    .foregroundStyle(.secondary)
                }

                Divider()

                // Assignees + reviewers
                if !item.assignees.isEmpty {
                    detailRow("Assignees") {
                        HStack(spacing: 6) {
                            ForEach(item.assignees, id: \.login) { user in
                                userChip(user)
                            }
                        }
                    }
                }

                if let reviews = item.reviews, !reviews.isEmpty {
                    detailRow("Reviews") {
                        VStack(alignment: .leading, spacing: 4) {
                            ForEach(reviews, id: \.author.login) { r in
                                HStack(spacing: 6) {
                                    Image(systemName: reviewIcon(r.state))
                                        .foregroundStyle(reviewColor(r.state))
                                        .font(.caption)
                                    Text(r.author.login)
                                        .font(.caption)
                                }
                            }
                        }
                    }
                }

                if let additions = item.additions, let deletions = item.deletions {
                    detailRow("Changes") {
                        HStack(spacing: 8) {
                            Text("+\(additions)").foregroundStyle(.green).font(.subheadline.monospaced().bold())
                            Text("-\(deletions)").foregroundStyle(.red).font(.subheadline.monospaced().bold())
                        }
                    }
                }

                if let branch = item.headRefName {
                    detailRow("Branch") {
                        Text(branch)
                            .font(.caption.monospaced())
                            .padding(6)
                            .background(.fill.tertiary, in: RoundedRectangle(cornerRadius: 4))
                    }
                }

                if !item.labels.isEmpty {
                    detailRow("Labels") {
                        FlowLayout(spacing: 4) {
                            ForEach(item.labels) { label in
                                LabelBadge(label: label)
                            }
                        }
                    }
                }

                Divider()

                Button("Open on GitHub") { openURL(item.url) }
                    .buttonStyle(.borderedProminent)
            }
            .padding(20)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }

    private var stateLabel: String {
        if item.isDraft == true { return "Draft" }
        if item.isMerged { return "Merged" }
        return item.isOpen ? "Open" : "Closed"
    }

    private var stateColor: Color {
        if item.isMerged { return .purple }
        if !item.isOpen { return .red }
        if item.isDraft == true { return .gray }
        return .green
    }

    private func detailRow<Content: View>(_ label: String, @ViewBuilder content: () -> Content) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(label.uppercased())
                .font(.caption2.bold())
                .foregroundStyle(.secondary)
            content()
        }
    }

    private func userChip(_ user: GHUser) -> some View {
        Text(user.login)
            .font(.caption)
            .padding(.horizontal, 8)
            .padding(.vertical, 3)
            .background(.fill.secondary, in: Capsule())
    }

    private func reviewIcon(_ state: ReviewState) -> String {
        switch state {
        case .approved:         return "checkmark.circle.fill"
        case .changesRequested: return "xmark.circle.fill"
        case .commented:        return "bubble.left.fill"
        default:                return "clock.fill"
        }
    }

    private func reviewColor(_ state: ReviewState) -> Color {
        switch state {
        case .approved:         return .green
        case .changesRequested: return .red
        default:                return .orange
        }
    }
}

// Simple flow layout for wrapping labels
private struct FlowLayout: Layout {
    var spacing: CGFloat = 4

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let sizes = subviews.map { $0.sizeThatFits(.unspecified) }
        var x: CGFloat = 0, y: CGFloat = 0, rowHeight: CGFloat = 0
        let width = proposal.width ?? .infinity
        for size in sizes {
            if x + size.width > width && x > 0 { x = 0; y += rowHeight + spacing; rowHeight = 0 }
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        return CGSize(width: width, height: y + rowHeight)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let sizes = subviews.map { $0.sizeThatFits(.unspecified) }
        var x = bounds.minX, y = bounds.minY, rowHeight: CGFloat = 0
        for (i, subview) in subviews.enumerated() {
            let size = sizes[i]
            if x + size.width > bounds.maxX && x > bounds.minX {
                x = bounds.minX; y += rowHeight + spacing; rowHeight = 0
            }
            subview.place(at: CGPoint(x: x, y: y), proposal: .unspecified)
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
    }
}

private func openURL(_ string: String) {
    guard let url = URL(string: string) else { return }
    NSWorkspace.shared.open(url)
}

