import SwiftUI

struct SettingsView: View {
    @EnvironmentObject var appState: AppState

    @State private var owners: [OwnerOption] = []
    @State private var projects: [ProjectOption] = []
    @State private var isLoadingOwners = false
    @State private var isLoadingProjects = false
    @State private var saveMessage: String? = nil

    // Local edits
    @State private var owner: String = ""
    @State private var ownerType: OwnerType = .organization
    @State private var projectNumber: Int = 0
    @State private var statusFieldName: String = ""
    @State private var refreshInterval: Int = 300

    var body: some View {
        Form {
            // Account
            Section("Account") {
                if appState.isAuthenticated {
                    HStack {
                        Label("Signed in with GitHub", systemImage: "checkmark.seal.fill")
                            .foregroundStyle(.green)
                        Spacer()
                        Button("Sign Out", role: .destructive) {
                            appState.signOut()
                        }
                        .buttonStyle(.plain)
                        .foregroundStyle(.red)
                    }
                } else {
                    Button("Sign in with GitHub") {
                        Task { await appState.signIn() }
                    }
                    .buttonStyle(.borderedProminent)
                }
            }

            if appState.isAuthenticated {
                // Owner picker
                Section("Organization / User") {
                    HStack {
                        if isLoadingOwners {
                            ProgressView().controlSize(.small)
                        } else if owners.isEmpty {
                            Button("Load owners") { Task { await loadOwners() } }
                                .buttonStyle(.plain)
                                .foregroundStyle(.blue)
                        } else {
                            Picker("Owner", selection: Binding(
                                get: { owner },
                                set: { newOwner in
                                    owner = newOwner
                                    ownerType = owners.first(where: { $0.login == newOwner })?.ownerType ?? .organization
                                    projects = []
                                    projectNumber = 0
                                }
                            )) {
                                ForEach(owners) { o in
                                    HStack {
                                        Image(systemName: o.ownerType == .organization ? "building.2" : "person")
                                        Text(o.login)
                                    }
                                    .tag(o.login)
                                }
                            }
                            .labelsHidden()
                        }
                    }
                    .task { if owners.isEmpty { await loadOwners() } }
                }

                // Project picker
                Section("Project") {
                    HStack {
                        if isLoadingProjects {
                            ProgressView().controlSize(.small)
                        } else if !owner.isEmpty {
                            Picker("Project", selection: $projectNumber) {
                                Text("Select a project…").tag(0)
                                ForEach(projects) { p in
                                    Text("#\(p.number) \(p.title)").tag(p.number)
                                }
                            }
                            .labelsHidden()
                            .onChange(of: owner) { _, _ in Task { await loadProjects() } }
                            .task { if projects.isEmpty, !owner.isEmpty { await loadProjects() } }
                        } else {
                            Text("Select an owner first")
                                .foregroundStyle(.secondary)
                        }
                    }
                }

                // Field config
                Section("Field Names") {
                    TextField("Status field name", text: $statusFieldName)
                        .help("The name of the single-select field used as the board status column (e.g. \"Status\").")
                }

                // Refresh interval
                Section("Refresh") {
                    Picker("Interval", selection: $refreshInterval) {
                        Text("1 minute").tag(60)
                        Text("5 minutes").tag(300)
                        Text("10 minutes").tag(600)
                        Text("30 minutes").tag(1800)
                    }
                    .pickerStyle(.menu)
                }

                // Save
                Section {
                    HStack {
                        Button("Save & Reload") {
                            save()
                        }
                        .buttonStyle(.borderedProminent)
                        .disabled(!canSave)

                        if let msg = saveMessage {
                            Text(msg)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .transition(.opacity)
                        }
                    }
                }
            }
        }
        .formStyle(.grouped)
        .onAppear { loadFromConfig() }
    }

    // MARK: - Helpers

    private var canSave: Bool {
        !owner.isEmpty && projectNumber > 0 && !statusFieldName.isEmpty
    }

    private func loadFromConfig() {
        let c = appState.config
        owner = c.owner
        ownerType = c.ownerType
        projectNumber = c.projectNumber
        statusFieldName = c.statusFieldName.isEmpty ? "Status" : c.statusFieldName
        refreshInterval = c.refreshInterval
    }

    private func save() {
        appState.config.owner = owner
        appState.config.ownerType = ownerType
        appState.config.projectNumber = projectNumber
        appState.config.statusFieldName = statusFieldName
        appState.config.refreshInterval = refreshInterval
        appState.config.save()

        saveMessage = "Saved"
        Task {
            await appState.load()
            try? await Task.sleep(for: .seconds(2))
            saveMessage = nil
        }
    }

    private func loadOwners() async {
        guard let token = appState.token else { return }
        isLoadingOwners = true
        let svc = GitHubService(token: token)
        owners = (try? await svc.fetchOwners()) ?? []
        if owner.isEmpty, let first = owners.first { owner = first.login; ownerType = first.ownerType }
        isLoadingOwners = false
    }

    private func loadProjects() async {
        guard let token = appState.token, !owner.isEmpty else { return }
        isLoadingProjects = true
        let svc = GitHubService(token: token)
        projects = (try? await svc.fetchProjects(owner: owner, ownerType: ownerType)) ?? []
        isLoadingProjects = false
    }
}

