import SwiftUI

struct BoardItemCard: View {
    let item: BoardItem
    @State private var isHovered = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            // Type icon + title
            HStack(alignment: .top, spacing: 6) {
                Image(systemName: item.type == .issue ? "circle" : "arrow.triangle.pull")
                    .font(.caption2)
                    .foregroundStyle(item.type == .issue ? .green : .blue)
                    .padding(.top, 2)

                Text(item.title)
                    .font(.subheadline)
                    .lineLimit(3)
                    .fixedSize(horizontal: false, vertical: true)

                Spacer(minLength: 0)

                if item.type == .pullRequest {
                    CIStateDot(state: item.ciState ?? .none)
                        .frame(width: 8, height: 8)
                        .padding(.top, 3)
                }
            }

            // Labels
            if !item.labels.isEmpty {
                FlowLayoutCard(spacing: 3) {
                    ForEach(item.labels.prefix(3)) { label in
                        LabelBadge(label: label)
                    }
                }
            }

            // Footer: number + repo + assignees
            HStack(spacing: 6) {
                Text("#\(item.number)")
                    .font(.caption2.monospaced())
                    .foregroundStyle(.tertiary)

                if !item.repository.isEmpty {
                    Text(item.repository)
                        .font(.caption2)
                        .foregroundStyle(.tertiary)
                        .lineLimit(1)
                }

                Spacer()

                // Assignee avatars (initials only — no async image needed)
                HStack(spacing: -4) {
                    ForEach(item.assignees.prefix(3), id: \.login) { user in
                        initialsAvatar(user.login)
                    }
                }

                if item.type == .pullRequest, let reviews = item.reviews, !reviews.isEmpty {
                    ReviewDots(reviews: reviews)
                        .padding(.trailing, 0)
                }
            }
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(Color(NSColor.controlBackgroundColor))
                .shadow(color: .black.opacity(isHovered ? 0.12 : 0.06), radius: isHovered ? 4 : 2, y: 1)
        )
        .scaleEffect(isHovered ? 1.01 : 1)
        .animation(.easeOut(duration: 0.12), value: isHovered)
        .onHover { isHovered = $0 }
        .contentShape(Rectangle())
        .onTapGesture {
            guard let url = URL(string: item.url) else { return }
            NSWorkspace.shared.open(url)
        }
    }

    private func initialsAvatar(_ login: String) -> some View {
        let initials = String(login.prefix(2)).uppercased()
        let hue = Double(login.unicodeScalars.reduce(0) { $0 + Int($1.value) } % 360) / 360
        return ZStack {
            Circle()
                .fill(Color(hue: hue, saturation: 0.5, brightness: 0.8))
                .frame(width: 18, height: 18)
            Text(initials)
                .font(.system(size: 7, weight: .bold))
                .foregroundStyle(.white)
        }
        .overlay(Circle().stroke(Color(NSColor.controlBackgroundColor), lineWidth: 1.5))
    }
}

