struct SprintHubApp: App {
    @StateObject private var appState = AppState()

    var body: some Scene {
        // Menu bar popover
        MenuBarExtra {
            PopoverView()
                .environmentObject(appState)
        } label: {
            MenuBarLabel()
                .environmentObject(appState)
        }
        .menuBarExtraStyle(.window)

        // Main dashboard window
